package org.freecad.mobilelab;
import org.json.*;
public final class PartDesignDatumAdapterHostTest {
    static int checks;
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
    static JSONObject call(JSONObject q)throws Exception{JSONObject r=new JSONObject(CoreNative.request(q.toString()));check(r.getBoolean("ok"),r.optString("error"));return r.getJSONObject("state");}
    static JSONObject cmd(String s)throws Exception{return call(CoreCommandLine.parse(s));}
    static void bad(String s)throws Exception{JSONObject r=new JSONObject(CoreNative.request(CoreCommandLine.parse(s).toString()));check(!r.getBoolean("ok"),"Must reject "+s);}
    static void python(String s)throws Exception{JSONObject c=call(new JSONObject().put("op","python").put("code",s)).getJSONObject("python").getJSONObject("console");check(c.getString("error").isEmpty(),c.getString("error"));}
    static void volume(String n,double v)throws Exception{JSONObject r=cmd("ShapeInfo "+n).getJSONObject("shape_inspection");check(r.getBoolean("valid")&&r.getInt("solids")==1,"Closed single solid "+n);check(Math.abs(r.getDouble("volume")-v)<0.00001,"Analytic volume "+n+": "+r);}
    static void circle(String b,String s,double x,double y,double r,String plane,double z)throws Exception{cmd("BodySketch "+b+" "+s);cmd("SketchCircle "+s+" "+x+" "+y+" "+r);cmd("Constraint "+s+" Block 0");cmd("SketchPlane "+s+" "+plane+" 0 0 "+z);}
    public static void main(String[] a)throws Exception{
        System.load(a[3]);SignalProbe.capture();System.load(a[0]);CoreNative.initialize(a[1],a[2],a[1]);check(SignalProbe.preserved(),"JVM signals retained");cmd("NewDoc Datums");cmd("Body Body");
        cmd("BodyPlane Body WorkPlane 100 80");cmd("BodyAxis Body WorkAxis 100");cmd("BodyPoint Body WorkPoint");cmd("BodyFrame Body WorkFrame");
        JSONObject b=cmd("BodyInfo Body").getJSONObject("body_inspection");check(b.getJSONArray("solid_history").length()==0,"Datums excluded from solid history");check(b.getJSONArray("datums").length()==4,"Four native construction references");
        cmd("PartPlacement Body 10 20 30 0 0 0");check(cmd("DatumInfo WorkPoint").getJSONObject("datum_inspection").getJSONArray("origin_mm").getDouble(2)==30,"Construction-only Body placement");cmd("Undo");bad("PartPlacement Body 999999 0 0 0 0 0");
        for(String n:new String[]{"WorkPlane","WorkAxis","WorkPoint","WorkFrame"}){
            JSONObject info=cmd("DatumInfo "+n).getJSONObject("datum_inspection");check(info.getBoolean("construction")&&info.isNull("material_volume_mm3"),"Construction has no material volume");
            JSONObject preview=cmd("DatumPreview "+n).getJSONObject("wire_preview");check(preview.getBoolean("construction"),"Construction preview labelled");WireFrame w=new WireFrame(preview);check(w.pointCount>1&&w.pointCount<32,"Finite bounded viewport guides");
            float[] p=w.project(0,0,0,800,600,30,20,1,0,0);check(Float.isFinite(p[0])&&Float.isFinite(p[1]),"Finite guide projection");
            bad("ShapeInfo "+n);bad("Preview "+n);bad("ExportStep "+n+" Datum.step");
        }
        cmd("Add PlaneAlias Link");cmd("Link PlaneAlias WorkPlane");cmd("Add AxisAlias Link");cmd("Link AxisAlias WorkAxis");
        for(String n:new String[]{"PlaneAlias","AxisAlias"}){bad("ShapeInfo "+n);bad("Preview "+n);bad("ExportStep "+n+" Alias.step");}
        cmd("DatumPose Body WorkPlane 1 2 3 0 0 0");cmd("BodySketchDatum Body WorkPlane Profile");cmd("SketchCircle Profile 0 0 1");cmd("Constraint Profile Block 0");cmd("Pad Body Profile Pad 5");volume("Body",5*Math.PI);
        python("d=App.ActiveDocument\nassert d.Profile.MapMode=='ObjectXY' and d.Profile.AttachmentSupport[0][0]==d.WorkPlane and list(d.Profile.AttachmentSupport[0][1])==['']\nassert d.Pad.Profile[0]==d.Profile and d.Body.Tip==d.Pad\nassert abs(d.Pad.Shape.CenterOfMass.z-5.5)<1e-6\nassert d.WorkPlane.TypeId=='PartDesign::Plane' and not d.WorkPlane.Shape.Edges\nassert d.WorkAxis.TypeId=='PartDesign::Line' and not d.WorkAxis.Shape.Vertexes\nassert d.WorkPoint.TypeId=='PartDesign::Point' and len(d.WorkPoint.Shape.Vertexes)==1\nassert d.WorkFrame.TypeId=='PartDesign::CoordinateSystem'");
        cmd("DatumPose Body WorkPlane 5 6 7 0 30 0");volume("Body",5*Math.PI);
        python("d=App.ActiveDocument\nexpected=d.WorkPlane.Placement.multVec(App.Vector(0,0,2.5))\nassert (d.Pad.Shape.CenterOfMass-expected).Length<1e-6");cmd("Undo");cmd("Redo");
        cmd("Set WorkPlane.Length 2 cm");cmd("Set WorkPlane.Width 3 cm");cmd("Set WorkAxis.Length 4 cm");
        check(cmd("DatumInfo WorkPlane").getJSONObject("datum_inspection").getDouble("display_length_mm")==20,"Native display dimension accepts units");
        cmd("Body FrameBody");cmd("BodyFrame FrameBody Frame");cmd("DatumPose FrameBody Frame 0 0 3 0 0 0");cmd("BodySketchDatum FrameBody Frame FrameProfile");cmd("SketchCircle FrameProfile 0 0 2");cmd("Constraint FrameProfile Block 0");cmd("Pad FrameBody FrameProfile FramePad 4");volume("FrameBody",16*Math.PI);
        cmd("DatumPose FrameBody Frame 0 0 8 0 0 0");volume("FrameBody",16*Math.PI);python("assert abs(App.ActiveDocument.FramePad.Shape.BoundBox.ZMin-8)<1e-6");
        cmd("DatumPose Body WorkAxis 4 5 6 0 90 0");cmd("DatumPose Body WorkPoint 3 4 5 0 0 0");
        python("d=App.ActiveDocument\nassert (d.WorkPoint.Shape.Vertexes[0].Point-App.Vector(3,4,5)).Length<1e-9\nassert d.WorkAxis.Shape.Edges[0].Curve.Direction.dot(d.WorkAxis.Placement.Rotation.multVec(App.Vector(0,0,1)))>1-1e-9");
        cmd("PartPlacement FrameBody 10 20 30 30 20 10");volume("FrameBody",16*Math.PI);JSONObject frame=cmd("DatumInfo Frame").getJSONObject("datum_inspection");check(frame.getJSONArray("origin_mm").getDouble(2)>30,"Construction inspection includes Body placement");cmd("Undo");
        for(String s:new String[]{"Set WorkPlane.Length 0 mm","Set WorkPlane.Width 10001 mm","Set WorkAxis.Length -1 mm","Set WorkPlane.ResizeMode 0","Set WorkPoint.Placement 0","Set WorkPlane.MapMode 1","Set WorkPlane.MapReversed true","BodyTip Body WorkPlane","Remove WorkPlane","RemoveDatum Body WorkPlane","DatumPose FrameBody WorkPoint 0 0 0 0 0 0","SketchPlane Profile XY 0 0 0","SketchPlacement Profile 0 0 0 0 0 0","SketchOffset Profile 0 0 1 0 0 0","SketchAttach Profile WorkPlane Face1","External Profile WorkAxis Edge1","BodySketchDatum Body WorkAxis BadAxisProfile","BodySketchDatum Body Frame ForeignProfile","BodySketchDatum Body WorkFrame Profile"})bad(s);
        bad("DatumPose Body WorkPlane 999999 0 0 0 0 0");volume("Body",5*Math.PI);
        cmd("DeleteConstraint FrameProfile 0");cmd("Constraint FrameProfile Radius 0 2");bad("ConstraintExpression FrameProfile 0 1e100");cmd("Datum FrameProfile 0 3 mm");volume("FrameBody",36*Math.PI);cmd("Undo");
        cmd("BodySketchDatum Body WorkFrame BudgetProfile");bad("SketchCircle BudgetProfile 0 0 1000001");bad("SketchCircle BudgetProfile 999999 0 10");python("assert App.ActiveDocument.BudgetProfile.GeometryCount==0");
        cmd("SketchDetach Profile");python("d=App.ActiveDocument\nassert d.Profile.MapMode=='Deactivated' and not d.Profile.AttachmentSupport\ndetached=d.Pad.Shape.CenterOfMass");
        cmd("DatumPose Body WorkPlane 5 6 20 0 0 0");python("assert (App.ActiveDocument.Pad.Shape.CenterOfMass-detached).Length<1e-6");cmd("Undo");cmd("Undo");python("assert App.ActiveDocument.Profile.MapMode=='ObjectXY'");
        cmd("RemoveDatum Body WorkPoint");bad("DatumInfo WorkPoint");cmd("Undo");cmd("Redo");cmd("Undo");
        cmd("Begin AtomicDatum");cmd("DatumPose Body WorkPlane 10 20 30 0 0 0");bad("Set WorkAxis.Length 0 mm");volume("Body",5*Math.PI);python("d=App.ActiveDocument\nassert (d.WorkPlane.Placement.Base-App.Vector(5,6,7)).Length<1e-9");
        cmd("Body HoleBody");circle("HoleBody","HoleBase",0,0,6,"XY",0);cmd("Pad HoleBody HoleBase HolePad 10");cmd("BodyPlane HoleBody HolePlane 20 20");cmd("DatumPose HoleBody HolePlane 0 0 10 0 0 0");cmd("BodySketchDatum HoleBody HolePlane HoleProfile");cmd("SketchCircle HoleProfile 0 0 1");cmd("Constraint HoleProfile Block 0");cmd("BodyHole HoleBody HoleProfile Hole 2 4");volume("HoleBody",356*Math.PI);bad("DatumPose HoleBody HolePlane 0 0 10 0 30 0");bad("DatumPose HoleBody HolePlane 0 0 0 0 0 0");volume("HoleBody",356*Math.PI);
        cmd("Body HelixBody");cmd("BodyPlane HelixBody Meridian 20 20");cmd("DatumPose HelixBody Meridian 0 0 0 0 0 90");cmd("BodySketchDatum HelixBody Meridian Radial");cmd("SketchCircle Radial 5 0 0.5");cmd("Constraint Radial Block 0");cmd("BodyAddHelix HelixBody Radial Helix 3 6");
        check(Math.abs(cmd("ShapeInfo HelixBody").getJSONObject("shape_inspection").getDouble("volume")-5*Math.PI*Math.PI)<0.001,"Original helix on native Datum meridian");bad("DatumPose HelixBody Meridian 0 0 0 0 0 0");
        cmd("Body PipeBody");cmd("BodyPlane PipeBody SectionPlane 20 20");cmd("BodySketchDatum PipeBody SectionPlane PipeProfile");cmd("SketchCircle PipeProfile 0 0 1");cmd("Constraint PipeProfile Block 0");cmd("BodySketch PipeBody PipePath");cmd("SketchLine PipePath 0 0 0 6");cmd("Constraint PipePath Block 0");cmd("SketchPlane PipePath XZ 0 0 0");cmd("BodyAddPipe PipeBody PipeProfile PipePath Edge1 Pipe");volume("PipeBody",6*Math.PI);bad("DatumPose PipeBody SectionPlane 0 0 1 0 0 0");volume("PipeBody",6*Math.PI);
        cmd("Save Datums.FCStd");
        Process cold=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-cp",System.getProperty("java.class.path"),"org.freecad.mobilelab.PartDesignDatumColdRestoreHostTest",a[0],a[1],a[2]).inheritIO().start();check(cold.waitFor()==0,"Original Datum restoration in a fresh JVM/interpreter");
        python("import zipfile,xml.etree.ElementTree as ET,mobile_core\nroot=mobile_core._root\nwith zipfile.ZipFile(root/'Datums.FCStd') as z:saved={n:z.read(n) for n in z.namelist()}\ndef datum_fixture(filename,obj,prop,tag,attribute,value):\n    tree=ET.fromstring(saved['Document.xml'])\n    node=tree.find(\"./ObjectData/Object[@name='\"+obj+\"']/Properties/Property[@name='\"+prop+\"']/\"+tag)\n    assert node is not None\n    node.set(attribute,value)\n    xml=ET.tostring(tree)\n    with zipfile.ZipFile(root/('BadDatum'+filename+'.FCStd'),'w') as z:\n        for n,b in saved.items():z.writestr(n,xml if n=='Document.xml' else b)");
        String[] changes={"'Length','WorkPlane','Length','Float','value','0'","'Width','WorkPlane','Width','Float','value','10001'","'SizeMode','WorkPlane','ResizeMode','Integer','value','0'","'RootMode','WorkPlane','MapMode','Integer','value','2'","'Engine','WorkPlane','AttacherType','String','value','Attacher::AttachEngine3D'","'Position','WorkPlane','Placement','PropertyPlacement','Px','nan'","'Quaternion','WorkPlane','Placement','PropertyPlacement','Q3','0'","'Offset','WorkPlane','AttachmentOffset','PropertyPlacement','Px','1'","'Reverse','WorkPlane','MapReversed','Bool','value','true'","'ProfileMode','Profile','MapMode','Integer','value','0'","'ProfileOffset','Profile','AttachmentOffset','PropertyPlacement','Px','1'","'ProfileReverse','Profile','MapReversed','Bool','value','true'","'Foreign','Profile','AttachmentSupport','LinkSubList/Link','obj','Frame'","'Cycle','Profile','AttachmentSupport','LinkSubList/Link','obj','Pad'","'Element','Profile','AttachmentSupport','LinkSubList/Link','sub','Face1'","'GeoCount','Profile','Geometry','GeometryList','count','1000000'","'ConstraintCount','Profile','Constraints','ConstraintList','count','1000000'","'ReferenceCount','Profile','ExternalGeometry','LinkSubList','count','1000000'"};
        for(String mutation:changes)python("datum_fixture("+mutation+")");
        for(String n:new String[]{"Length","Width","SizeMode","RootMode","Engine","Position","Quaternion","Offset","Reverse","ProfileMode","ProfileOffset","ProfileReverse","Foreign","Cycle","Element","GeoCount","ConstraintCount","ReferenceCount"})bad("Open BadDatum"+n+".FCStd");volume("Body",5*Math.PI);
        cmd("ExportStep FrameBody DatumDriven.step");cmd("ImportStep ModelCopy DatumDriven.step");volume("ModelCopy",16*Math.PI);
        cmd("Close");cmd("Open Datums.FCStd");volume("Body",5*Math.PI);volume("FrameBody",16*Math.PI);volume("HoleBody",356*Math.PI);volume("PipeBody",6*Math.PI);
        python("d=App.ActiveDocument\nassert d.Profile.AttachmentSupport[0][0]==d.WorkPlane\nassert d.FrameProfile.AttachmentSupport[0][0]==d.Frame\nassert d.Body.Tip==d.Pad and d.FrameBody.Tip==d.FramePad\nassert d.Helix.Profile[0].MapMode=='ObjectXY'");
        System.out.println("PASS original Datum JNI checks: "+checks);
    }
}
